  "visual-aids.js": "// Visual support aids: a reading guide (a highlighted band that follows the\n// pointer / keyboard focus to help tracking) and a full-page colour overlay\n// (for visual stress / Irlen sensitivity). Both are injected at runtime, need\n// no network, and persist across reloads via localStorage. The overlay layers\n// are pointer-events:none so they never intercept clicks or keyboard use.\n\nclass VisualAidsManager {\n    constructor() {\n        this.storageKey = \"user-visual-aids\";\n        this.reduceMotion = !!(window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches);\n\n        this.guideEl = null;\n        this.overlayEl = null;\n        this.guideOn = false;\n\n        this.guideToggle = document.getElementById(\"reading-guide-toggle\");\n        this.overlayColour = document.getElementById(\"overlay-colour\");\n        this.overlayOpacity = document.getElementById(\"overlay-opacity\");\n        this.overlayOpacityValue = document.getElementById(\"overlay-opacity-value\");\n\n        this.onPointerMove = this.onPointerMove.bind(this);\n        this.onFocusMove = this.onFocusMove.bind(this);\n\n        this.buildLayers();\n        this.setupControls();\n        this.restore();\n        console.log(\"✅ Visual aids initialised\");\n    }\n\n    buildLayers() {\n        this.guideEl = document.createElement(\"div\");\n        this.guideEl.id = \"reading-guide\";\n        this.guideEl.setAttribute(\"aria-hidden\", \"true\");\n        document.body.appendChild(this.guideEl);\n\n        this.overlayEl = document.createElement(\"div\");\n        this.overlayEl.id = \"colour-overlay\";\n        this.overlayEl.setAttribute(\"aria-hidden\", \"true\");\n        document.body.appendChild(this.overlayEl);\n    }\n\n    setupControls() {\n        if (this.guideToggle) {\n            this.guideToggle.addEventListener(\"change\", (e) => this.setGuide(e.target.checked));\n        }\n        if (this.overlayColour) {\n            this.overlayColour.addEventListener(\"change\", () => this.applyOverlay());\n        }\n        if (this.overlayOpacity && this.overlayOpacityValue) {\n            this.overlayOpacity.addEventListener(\"input\", (e) => {\n                const pct = Math.round(parseFloat(e.target.value) * 100);\n                this.overlayOpacityValue.textContent = pct + \"%\";\n                this.overlayOpacity.setAttribute(\"aria-valuetext\", pct + \" percent\");\n                this.applyOverlay();\n            });\n        }\n    }\n\n    setGuide(on) {\n        this.guideOn = on;\n        this.guideEl.style.display = on ? \"block\" : \"none\";\n        if (on) {\n            document.addEventListener(\"pointermove\", this.onPointerMove);\n            document.addEventListener(\"focusin\", this.onFocusMove);\n            this.announce(\"Reading guide on\");\n        } else {\n            document.removeEventListener(\"pointermove\", this.onPointerMove);\n            document.removeEventListener(\"focusin\", this.onFocusMove);\n            this.announce(\"Reading guide off\");\n        }\n        this.save();\n    }\n\n    onPointerMove(e) {\n        this.guideEl.style.top = e.clientY + \"px\";\n    }\n\n    onFocusMove(e) {\n        const t = e.target;\n        if (!t || !t.getBoundingClientRect || t.closest(\"#sidebar\")) return;\n        const rect = t.getBoundingClientRect();\n        this.guideEl.style.top = rect.top + rect.height / 2 + \"px\";\n    }\n\n    applyOverlay() {\n        const colour = this.overlayColour ? this.overlayColour.value : \"none\";\n        const opacity = this.overlayOpacity ? parseFloat(this.overlayOpacity.value) : 0;\n        if (colour === \"none\" || opacity <= 0) {\n            this.overlayEl.style.display = \"none\";\n        } else {\n            this.overlayEl.style.background = colour;\n            this.overlayEl.style.opacity = String(opacity);\n            this.overlayEl.style.display = \"block\";\n        }\n        this.save();\n    }\n\n    save() {\n        try {\n            localStorage.setItem(this.storageKey, JSON.stringify({\n                guide: this.guideOn,\n                colour: this.overlayColour ? this.overlayColour.value : \"none\",\n                opacity: this.overlayOpacity ? this.overlayOpacity.value : \"0\",\n            }));\n        } catch (e) {\n            /* storage unavailable — ignore */\n        }\n    }\n\n    restore() {\n        let saved;\n        try {\n            const raw = localStorage.getItem(this.storageKey);\n            if (!raw) return;\n            saved = JSON.parse(raw);\n        } catch (e) {\n            return;\n        }\n        if (!saved || typeof saved !== \"object\") return;\n\n        if (saved.colour !== undefined && this.overlayColour) this.overlayColour.value = saved.colour;\n        if (saved.opacity !== undefined && this.overlayOpacity && this.overlayOpacityValue) {\n            this.overlayOpacity.value = saved.opacity;\n            const pct = Math.round(parseFloat(saved.opacity) * 100);\n            this.overlayOpacityValue.textContent = pct + \"%\";\n            this.overlayOpacity.setAttribute(\"aria-valuetext\", pct + \" percent\");\n        }\n        this.applyOverlay();\n\n        if (saved.guide && this.guideToggle) {\n            this.guideToggle.checked = true;\n            this.setGuide(true);\n        }\n    }\n\n    announce(message) {\n        if (typeof window.announceToScreenReader === \"function\") {\n            window.announceToScreenReader(message, { delay: 150 });\n        }\n    }\n}\n\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n    try {\n        window.visualAidsManager = new VisualAidsManager();\n    } catch (error) {\n        console.error(\"❌ Failed to initialise Visual Aids:\", error);\n    }\n});\n\nif (typeof window !== \"undefined\") {\n    window.VisualAidsManager = VisualAidsManager;\n}\n",
